import{_ as t,H as a,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"复习课（一） | 管理方法论和角色认知","description":"","frontmatter":{},"headers":[{"level":2,"title":"一、管理方法论","slug":"一、管理方法论","link":"#一、管理方法论","children":[]},{"level":2,"title":"二、分述“管理方法论”的五大方面、18个要素","slug":"二、分述-管理方法论-的五大方面、18个要素","link":"#二、分述-管理方法论-的五大方面、18个要素","children":[{"level":3,"title":"（一）角色认知","slug":"一-角色认知","link":"#一-角色认知","children":[]}]}],"relativePath":"技术管理实战36讲/复习课（一）-管理方法论和角色认知.md","filePath":"技术管理实战36讲/复习课（一）-管理方法论和角色认知.md","lastUpdated":1779820334000}'),s={name:"技术管理实战36讲/复习课（一）-管理方法论和角色认知.md"};function r(E,e,o,g,l,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="复习课-一-管理方法论和角色认知" tabindex="-1">复习课（一） | 管理方法论和角色认知 <a class="header-anchor" href="#复习课-一-管理方法论和角色认知" aria-label="Permalink to &quot;复习课（一） | 管理方法论和角色认知&quot;">​</a></h1><hr><p>你好，我是这个专栏的编辑琳琳。非常荣幸能有机会以“第一读者”这个身份参与到这个专栏中，“近水楼台先得月”，不得不说这个专栏也给我很多的启发和指引。</p><p>看到我们可爱的用户有提及做思维导图的需求，所以借此机会我会将整个专栏梳理一遍，并补充相关的脑图，希望能帮助到百忙之中的你。</p><p>那接下来你就跟着我一起复习吧！</p><h2 id="一、管理方法论" tabindex="-1">一、管理方法论 <a class="header-anchor" href="#一、管理方法论" aria-label="Permalink to &quot;一、管理方法论&quot;">​</a></h2><p>在 <a href="https://time.geekbang.org/column/article/64689" target="_blank" rel="noreferrer">第35篇《从空降谈管理方法论的积累》</a> 中，作者借助“空降”这个话题总结了管理方法论，并勾画出一幅“管理全景图”。我印象很是深刻，也正是这篇文章让我对整个专栏有了一个整体上的“回顾”与“俯视”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/67a4159cabd32da3da23a9a0ef378495.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/67a4159cabd32da3da23a9a0ef378495.png" alt=""></a></p><p>这幅“全景图”是作者结合管理的具体工作场景和所遇痛点，由粗到细、由浅入深一步步铺展开来的。</p><p>在 <a href="https://time.geekbang.org/column/article/14534" target="_blank" rel="noreferrer">第8篇文章《管理到底都做哪些事儿？》</a> 中，作者介绍的管理框架——“管理三明治”，把无所不在的空气般的认知作为“天”，把承载一切管理工作的沟通作为“地”，把管理者需要做的“看方向”“带人”“做事”放在中间，就组成了管理者的管理框架。 <strong>这就是“管理要做的这些事儿”</strong>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/c129b5d3a3a1fd1848d8453b0cf50183.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/c129b5d3a3a1fd1848d8453b0cf50183.png" alt=""></a></p><p>“管理三明治”——管理框架示意图（果见）</p><p>为便于我们“按图索骥”和“对症下药”，作者根据工作场景将“看方向”“带人”和“做事”拆解和细化出13个要素，形成了“管理全景图”。当然，我们也可以提炼和总结属于自己的管理心得和方法论，放置要素外围的留白处，私人订制自己的“管理全景图”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/bdf3a3c6a4d0e50b6c65dcdee7eb6dc1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/bdf3a3c6a4d0e50b6c65dcdee7eb6dc1.png" alt=""></a></p><p>在 <a href="https://time.geekbang.org/column/article/41968" target="_blank" rel="noreferrer">第28篇《管理沟通那些事儿》</a> 中，作者又从“目的”“内容”“通道”和“影响力”四部分拆解出一个管理沟通的框架，这才最终成型了上面展示的“管理全景图-沟通扩展版”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/a7cdf7790422245a87b978b53872b764.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/a7cdf7790422245a87b978b53872b764.png" alt=""></a></p><p>“果见管理沟通框架”</p><p>至此，我明白了应该要从哪些要素着手拆解和分析管理工作，也学习到了要从哪些方面去系统地积累自己的方法论。这里，我将这五大方面、18个要素汇总为如下图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/af4ff71a905baddbca6f19fd8673b329.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/af4ff71a905baddbca6f19fd8673b329.png" alt=""></a></p><p>管理方法论图示</p><h2 id="二、分述-管理方法论-的五大方面、18个要素" tabindex="-1">二、分述“管理方法论”的五大方面、18个要素 <a class="header-anchor" href="#二、分述-管理方法论-的五大方面、18个要素" aria-label="Permalink to &quot;二、分述“管理方法论”的五大方面、18个要素&quot;">​</a></h2><h3 id="一-角色认知" tabindex="-1">（一）角色认知 <a class="header-anchor" href="#一-角色认知" aria-label="Permalink to &quot;（一）角色认知&quot;">​</a></h3><p>“既然你被任命为这个团队的负责人，你就是此次时刻带领这个团队最合适的人”，理顺这些自我认知后，那么接下来，还会遇到角色认知的问题。本专栏关于这个话题讲解了角色转换和常见的管理误区。（为便于你、我总体把控和复习，我将它们用思维导图的形式展示出来了。）</p><p><strong>1. 角色转换</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/9aa090d3029b7751f79cddbcdc6e2141.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/9aa090d3029b7751f79cddbcdc6e2141.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/14762" target="_blank" rel="noreferrer">第9篇《从工程师到管理者，角色都发生了哪些变化？》</a>（最后对比部分，上为工程师，下为管理者）</p><p><strong>2. 常见的管理误区</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/fa172a62bda48d1c7f16438f8822500f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2/images/67186/fa172a62bda48d1c7f16438f8822500f.png" alt=""></a></p><p>总结自 <a href="https://time.geekbang.org/column/article/17830" target="_blank" rel="noreferrer">第10篇《新经理常踩的坑儿有哪些？》</a></p><p>至于另外四个方面的内容复习，我会在接下来的文章中一一展示出来，敬请关注。</p><hr>',31)])])}const b=t(s,[["render",r]]);export{h as __pageData,b as default};
